package ratelimit

import "testing"

func TestLimiter_Burst(t *testing.T) {
	limiter := &Limiter{tokens: 5, maxTokens: 5, refillRate: 1}
	for i := 0; i < 5; i++ {
		if !limiter.Allow() {
			t.Fatalf("request %d should be allowed", i)
		}
	}
	if limiter.Allow() {
		t.Fatal("6th request should be throttled")
	}
}
